import sys,numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();spec=r.spec()
for cam,roi in [('over_shoulder_left_camera',(650,600,840,720)),('egocentric_mirrored_camera',(560,0,740,180))]:
 im=np.array(Image.open('/app/output/p15_'+cam+'.png'));d=np.load('/app/output/p15_depth_'+cam+'.npy');K=np.array(spec['cameras'][cam]['intrinsic_cv']);E=np.array(spec['cameras'][cam]['mount']['extrinsic_cv']);R=E[:,:3];t=E[:,3];x0,y0,x1,y1=roi
 v,u=np.mgrid[y0:y1,x0:x1];rgb=im[y0:y1,x0:x1].astype(int);z=d[y0:y1,x0:x1];
 cc=np.stack([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z],-1);w=(cc-t)@np.linalg.inv(R).T
 mask=(rgb[...,0]>195)&(rgb[...,1]>195)&(rgb[...,2]>195)&(z>0)&(z<3)
 pts=w[mask];print('\n',cam,'white',len(pts),'rgb samples');
 if len(pts):print('quantiles',np.round(np.quantile(pts,[0,.1,.5,.9,1],axis=0),3));
 # list chosen grid pixels center-ish
 for v0,u0 in [(y0+20,x0+20),(y0+40,x0+60),(y0+60,x0+80),(y0+80,x0+100),(y0+100,x0+120)]:
  if v0<im.shape[0] and u0<im.shape[1]:
   zz=float(d[v0,u0]);c=np.array([(u0-K[0,2])*zz/K[0,0],(v0-K[1,2])*zz/K[1,1],zz]);ww=np.linalg.inv(R)@(c-t);print((u0,v0),im[v0,u0],round(zz,3),np.round(ww,3))
PY

